<?php elseif($success): $received=RGR_Refund::request($success); ?><div class="rgr-calm"><div class="result"><section class="panel"><div class="result-icon"><?php echo RGR_Centre::icon(); ?></div><p class="eyebrow">REQUEST RECEIVED</p><h1>You’re in good hands.</h1><p class="intro">Request #<?php echo (int)$success; ?> is with our team for review. This confirms receipt, not approval of a return or refund.</p><div class="result-items"><?php if($received && RGR_Refund::owned($received,$user))RGR_Calm::products($received); ?></div><p>Submitting a request does not automatically cancel an order or issue a refund.</p><a class="btn" href="<?php echo esc_url(RGR_Calm::url($success)); ?>">View request details</a></section></div></div>
<?php elseif(!$order): ?>
<section class="rgr-panel"><div class="rgr-section-head"><div><p class="rgr-eyebrow">START WITH YOUR ORDER</p><h2><?php echo $cancel?'Orders still in progress.':'Find your order.'; ?></h2></div><?php echo RGR_Centre::icon($mode); ?></div>
<?php $page=max(1,absint($_GET['request_page']??1));$orders=wc_get_orders(array('customer_id'=>$user,'status'=>$cancel?array('pending','processing','on-hold','failed'):array('processing','on-hold','completed'),'limit'=>10,'page'=>$page,'paginate'=>true,'orderby'=>'date','order'=>'DESC'));if(!$orders->orders): ?><p>No matching orders here yet. <?php echo $cancel?'Completed and refunded orders are not listed for cancellation.':'If you have a concern about another order, our team can help.'; ?></p><?php endif; ?>
