<?php if($orders->max_num_pages>1): ?><nav class="rgr-actions" aria-label="Order pages"><?php foreach(array($page-1=>'Previous',$page+1=>'Next')as $n=>$label)if($n>=1&&$n<=$orders->max_num_pages): ?><a class="rgr-button rgr-secondary" href="<?php echo esc_url(add_query_arg('request_page',$n,RGR_Centre::url($mode))); ?>"><?php echo esc_html($label); ?></a><?php endif; ?></nav><?php endif; ?></section>
<?php else: ?>
<div class="rgr-layout"><div class="rgr-main-column">
<section class="rgr-panel"><div class="rgr-section-head"><div><p class="rgr-eyebrow"><?php echo $fixture?'SAMPLE ORDER':'ORDER #'.esc_html($order->get_order_number()); ?></p><h2><?php echo $review?'One final check.':'Your products. Your choice.'; ?></h2></div><span class="rgr-order-state"><?php echo $fixture?'Sample status':esc_html(wc_get_order_status_name($order->get_status())); ?></span></div>
<?php if($ctx['blocked']): ?><div class="rgr-alert"><?php echo esc_html($ctx['blocked']); ?></div><?php if($cancel): ?><a class="rgr-button rgr-secondary" href="<?php echo esc_url(RGR_Centre::url('return',$id)); ?>">Check return options</a><?php endif; ?>
<?php elseif($review): ?>
<p>Are you sure you want to request <?php echo $cancel?'cancellation':'a return'; ?> for these products?</p><div class="rgr-review-items"><?php foreach($review['selection']as $item_id=>$qty): ?><div><strong><?php echo esc_html($ctx['items'][$item_id]['name']??'Product'); ?></strong><span>Quantity <?php echo (int)$qty; ?></span></div><?php endforeach; ?></div>
<dl class="rgr-summary"><div><dt>Request</dt><dd><?php echo esc_html(RGR_Centre::types($mode)[$review['type']]??$review['type']); ?><?php if(!empty($review['refund'])){$rf=RGR_Refund::open($review['refund'],'draft:'.$id.':'.$user);echo '<p>Refund destination: '.esc_html(RGR_Refund::summary($rf)).'</p>';} ?></dd></div><div><dt>Your reason</dt><dd><?php echo esc_html($review['reason']); ?></dd></div></dl>
<form method="post" action="<?php echo esc_url(RGR_Centre::url($mode,$id)); ?>" class="rgr-form"><input type="hidden" name="rgr_step" value="confirm"><input type="hidden" name="order_id" value="<?php echo (int)$id; ?>"><input type="hidden" name="review_token" value="<?php echo esc_attr($review['token']); ?>"><?php wp_nonce_field(RGR_Centre::nonce($mode,$id),'rgr_nonce'); ?><label class="rgr-consent"><input type="checkbox" name="confirm_items" value="1" required><span>I have checked the selected products and quantities, and I want to submit this request for review.</span></label><div class="rgr-actions"><button class="rgr-button" type="submit">Confirm <?php echo $cancel?'cancellation':'return'; ?> request</button><a class="rgr-button rgr-secondary" href="<?php echo esc_url(RGR_Centre::url($mode,$id)); ?>">Edit selection</a></div></form>
<?php else:$available=array_filter($ctx['items'],function($r){return $r['code']==='eligible';}); ?>
<p class="rgr-small">Select individual products and quantities. Nothing is submitted until you review and confirm.</p>
<form method="post" action="<?php echo esc_url($fixture?'#preview-only':RGR_Centre::url($mode,$id)); ?>" class="rgr-form"><input type="hidden" name="rgr_step" value="review"><input type="hidden" name="order_id" value="<?php echo (int)$id; ?>"><?php if(!$fixture)wp_nonce_field(RGR_Centre::nonce($mode,$id),'rgr_nonce'); ?>
<div class="rgr-items"><?php foreach($ctx['items']as $row):$enabled=$row['code']==='eligible'; ?><article class="rgr-item <?php echo $enabled?'':'rgr-item-disabled'; ?>"><label class="rgr-item-label"><input type="checkbox" name="selected[<?php echo (int)$row['id']; ?>]" value="1" <?php disabled(!$enabled); ?>><span><strong><?php echo esc_html($row['name']); ?></strong><span class="rgr-item-status" data-eligibility="<?php echo esc_attr($row['code']); ?>"><?php echo esc_html($row['message']); ?></span><?php if($row['window']): ?><small><?php echo esc_html($row['window']); ?></small><?php endif; ?></span></label><?php if($enabled): ?><label class="rgr-quantity"><span>Quantity</span><input aria-label="Quantity for <?php echo esc_attr($row['name']); ?>" type="number" inputmode="numeric" min="1" max="<?php echo (int)$row['remaining']; ?>" step="1" name="quantity[<?php echo (int)$row['id']; ?>]" value="1"><small>of <?php echo (int)$row['remaining']; ?> available</small></label><?php endif; ?></article><?php endforeach; ?></div>
<?php if($available&&RGR_Centre::types($mode)): ?><label class="rgr-field"><span>Request type</span><select name="request_type"><?php foreach(RGR_Centre::types($mode)as $key=>$label): ?><option value="<?php echo esc_attr($key); ?>"><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label><label class="rgr-field"><span><?php echo $cancel?'Reason for cancellation':'Tell us what happened'; ?></span><textarea name="reason" rows="3" minlength="5" maxlength="2000" required placeholder="A few details help our team review your request."></textarea></label><?php if(!$cancel)RGR_Refund::form_fields($order,$order->get_payment_method()==='cod'?'bank':'original'); ?><p class="rgr-small" data-rgr-selection aria-live="polite">No products selected yet.</p><button class="rgr-button" type="submit" <?php disabled($fixture); ?>>Review selected products<?php echo RGR_Centre::icon('return'); ?></button><?php else: ?><p class="rgr-alert">No products are currently eligible for this request. Please contact customer care if you have a concern.</p><?php endif; ?></form>
<?php endif; ?></section></div>
<aside class="rgr-side"><section class="rgr-note"><?php echo RGR_Centre::icon(); ?><h2>Checked before it’s sent.</h2><p><?php echo $cancel?'We recheck dispatch status and your selected quantities when you confirm. Shipped orders cannot be cancelled.':'We check each product’s own return window and any quantities already refunded or requested.'; ?></p><p>Requests are reviewed by our team. Submission does not automatically change your order or issue a refund.</p><?php if(!$cancel): ?><p class="rgr-small">The return window uses the recorded delivery date when available, otherwise the order’s completion date. A return requested before delivery is reviewed before collection.</p><?php endif; ?><a href="<?php echo esc_url(home_url('/refund_returns/')); ?>">Read the return policy</a></section></aside></div>
<?php endif; ?>
<footer class="rgr-help"><span class="rgr-help-icon"><?php echo RGR_Centre::icon(); ?></span><div><h2>Need assistance?</h2><p>Past the return window, unsure about eligibility, or something else on your mind?</p></div><a class="rgr-button rgr-secondary" href="<?php echo esc_url(home_url('/contact/')); ?>">Talk to customer care</a></footer>
